--
-- Name: book_summary; Type: VIEW; Schema: public; Owner: booklog_app
--

CREATE VIEW public.book_summary AS
 SELECT b.book_id,
    b.title,
    b.isbn,
    b.subtitle,
    b.cover_url,
    b.avg_rating,
    b.ratings_count,
    b.description,
    COALESCE(ARRAY( SELECT a.name
           FROM (public.book_author ba
             JOIN public.author a USING (author_id))
          WHERE (ba.book_id = b.book_id)
          ORDER BY a.name), '{}'::character varying[]) AS authors,
    COALESCE(ARRAY( SELECT g.name
           FROM (public.book_genre bg
             JOIN public.genre g USING (genre_id))
          WHERE (bg.book_id = b.book_id)
          ORDER BY g.name), '{}'::character varying[]) AS genres,
    b.language,
    b.page_count,
    b.pub_year
   FROM public.book b;


