--
-- Name: mv_active_users; Type: MATERIALIZED VIEW; Schema: public; Owner: booklog_reports
--

CREATE MATERIALIZED VIEW public.mv_active_users AS
 SELECT u.user_id,
    u.username,
    ( SELECT count(*) AS count
           FROM public.diary_entry d
          WHERE (d.user_id = u.user_id)) AS entries,
    ( SELECT count(*) AS count
           FROM public.diary_entry d
          WHERE ((d.user_id = u.user_id) AND (d.review_text IS NOT NULL))) AS reviews,
    ( SELECT count(*) AS count
           FROM public.comment c
          WHERE (c.user_id = u.user_id)) AS comments,
    ( SELECT count(*) AS count
           FROM public.list l
          WHERE (l.user_id = u.user_id)) AS lists
   FROM public.users u
  WITH NO DATA;


ALTER TABLE public.mv_active_users OWNER TO booklog_reports;

