    ADD CONSTRAINT genre_pkey PRIMARY KEY (genre_id);


--
-- Name: mv_genre_trends; Type: MATERIALIZED VIEW; Schema: public; Owner: booklog_reports
--

CREATE MATERIALIZED VIEW public.mv_genre_trends AS
 SELECT g.genre_id,
    g.name AS genre,
    (date_trunc('month'::text, (COALESCE(d.date_read, (d.created_at)::date))::timestamp with time zone))::date AS month,
    count(*) AS logs,
    round(avg(d.rating), 2) AS avg_rating
   FROM ((public.diary_entry d
     JOIN public.book_genre bg ON ((bg.book_id = d.book_id)))
     JOIN public.genre g ON ((g.genre_id = bg.genre_id)))
  GROUP BY g.genre_id, ((date_trunc('month'::text, (COALESCE(d.date_read, (d.created_at)::date))::timestamp with time zone))::date)
  WITH NO DATA;


ALTER TABLE public.mv_genre_trends OWNER TO booklog_reports;

--
-- Name: book book_pkey; Type: CONSTRAINT; Schema: public; Owner: booklog_app
--

ALTER TABLE ONLY public.book
    ADD CONSTRAINT book_pkey PRIMARY KEY (book_id);


--
-- Name: mv_most_read_books; Type: MATERIALIZED VIEW; Schema: public; Owner: booklog_reports
--

CREATE MATERIALIZED VIEW public.mv_most_read_books AS
 SELECT b.book_id,
    b.title,
    count(d.entry_id) AS times_logged,
    count(DISTINCT d.user_id) AS readers,
    round(avg(d.rating), 2) AS avg_user_rating,
    count(*) FILTER (WHERE d.is_liked) AS likes
   FROM (public.book b
     JOIN public.diary_entry d ON ((d.book_id = b.book_id)))
  GROUP BY b.book_id
  WITH NO DATA;


ALTER TABLE public.mv_most_read_books OWNER TO booklog_reports;

