--
-- Name: book audit_book_update; Type: TRIGGER; Schema: public; Owner: booklog_app
--

CREATE TRIGGER audit_book_update AFTER UPDATE ON public.book FOR EACH ROW WHEN ((((to_jsonb(old.*) - 'avg_rating'::text) - 'ratings_count'::text) IS DISTINCT FROM ((to_jsonb(new.*) - 'avg_rating'::text) - 'ratings_count'::text))) EXECUTE FUNCTION public.trg_audit();


